import { useEffect, useState } from "react";
import {
  Box,
  Typography,
  Breadcrumbs,
  Link as MUILink,
  Container,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  CircularProgress,
} from "@mui/material";
import { Link } from "react-router-dom";
import { Colors } from "../../Comman";
import axios from "../../axiosInstance";

const BusinessLeads = () => {
  const [leads, setLeads] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchLeads = async () => {
    try {
      setLoading(true);
      const res = await axios.get("/api/v1/leads/get-by-business");
      setLeads(res.data.data || []);
    } catch (err) {
      console.error("Error fetching leads", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, []);

  return (
    <Container maxWidth="xl" sx={{ py: 2 }}>
      <Typography
        variant="h5"
        align="center"
        gutterBottom
        sx={{
          mb: 3,
          fontFamily: "Poppins, sans-serif",
          color: "#2C3E50",
          letterSpacing: "2.5px",
          lineHeight: 1.8,
        }}
      >
        Business Leads
      </Typography>

      <Breadcrumbs
        aria-label="breadcrumb"
        sx={{
          mb: 5,
          backgroundColor: "#fff",
          padding: "20px",
          borderRadius: "12px",
          boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
          width: "fit-content",
        }}
      >
        <MUILink
          component={Link}
          to="/business/dashboard"
          sx={{ color: "inherit", textDecoration: "none" }}
        >
          Dashboard
        </MUILink>
        <Typography sx={{ color: "primary.main" }}>Leads</Typography>
      </Breadcrumbs>

      {loading ? (
        <Box textAlign="center" my={4}>
          <CircularProgress />
        </Box>
      ) : (
        <TableContainer component={Paper} sx={{ borderRadius: 2, boxShadow: 3 }}>
          <Table>
            <TableHead sx={{ bgcolor: Colors.LOGOColor }}>
              <TableRow>
                <TableCell sx={{ color: "white", fontWeight: 600 }}><b>#</b></TableCell>
                <TableCell sx={{ color: "white", fontWeight: 600 }}><b>Business Name</b></TableCell>
                <TableCell sx={{ color: "white", fontWeight: 600 }}><b>User Name</b></TableCell>
                <TableCell sx={{ color: "white", fontWeight: 600 }}><b>Email</b></TableCell>
                <TableCell sx={{ color: "white", fontWeight: 600 }}><b>Phone</b></TableCell>
                <TableCell sx={{ color: "white", fontWeight: 600 }}><b>Clicked At</b></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {leads.map((lead, index) => (
                <TableRow key={lead._id}>
                  <TableCell>{index + 1}</TableCell>
                  <TableCell>{lead.businessId?.businessName || "N/A"}</TableCell>
                  <TableCell>{lead.userId?.name || "Anonymous"}</TableCell>
                  <TableCell>{lead.userId?.email || "—"}</TableCell>
                  <TableCell>{lead.userId?.phone || "—"}</TableCell>
                  <TableCell>{new Date(lead.createdAt).toLocaleString()}</TableCell>
                </TableRow>
              ))}
              {leads.length === 0 && (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    No leads found.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Container>
  );
};

export default BusinessLeads;
