import React, { useEffect, useState } from "react";
import {
  Box,
  TextField,
  List,
  ListItem,
  ListItemText,
  Paper,
  InputAdornment,
  Typography,
  CircularProgress,
  IconButton,
  Divider,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import ClearIcon from "@mui/icons-material/Clear";
import MicIcon from "@mui/icons-material/Mic";
import axios from "../axiosInstance";
import { useNavigate } from "react-router-dom";

const staticSuggestions = ["School", "Hospital", "AC Repair", "Restaurant", "Coaching"];
const staticCategories = ["Education", "Healthcare", "Electronics", "Food", "Services"];

const SearchBar = () => {
  const [query, setQuery] = useState("");
  const [showDropdown, setShowDropdown] = useState(false);
  const [typingIndex, setTypingIndex] = useState(0);
  const [displayText, setDisplayText] = useState("");
  const [charIndex, setCharIndex] = useState(0);
  const [loading, setLoading] = useState(false);
  const [listening, setListening] = useState(false);
  const [results, setResults] = useState({
    businesses: [],
    products: [],
    categories: [],
  });
  const [recentSearches, setRecentSearches] = useState(() => {
    const saved = localStorage.getItem("recentSearches");
    return saved ? JSON.parse(saved) : [];
  });

  const navigate = useNavigate();

  // Typing effect
  useEffect(() => {
    const interval = setInterval(() => {
      const word = staticSuggestions[typingIndex];
      setDisplayText(word.slice(0, charIndex + 1));
      setCharIndex((prev) => prev + 1);

      if (charIndex >= word.length) {
        setTimeout(() => {
          setCharIndex(0);
          setTypingIndex((prev) => (prev + 1) % staticSuggestions.length);
        }, 1000);
      }
    }, 120);

    return () => clearInterval(interval);
  }, [charIndex, typingIndex]);

  // Fetch search results
  useEffect(() => {
    if (!query.trim()) {
      setResults({ businesses: [], products: [], categories: [] });
      return;
    }

    const timer = setTimeout(async () => {
      setLoading(true);
      try {
        const res = await axios.get(`/api/search?q=${query}`);
        setResults({
          businesses: res.data.data.businesses,
          products: res.data.data.products,
          categories: res.data.data.categories || [],
        });
      } catch (err) {
      } finally {
        setLoading(false);
      }
    }, 400);

    return () => clearTimeout(timer);
  }, [query]);

  // Save search
  const saveRecentSearch = (text) => {
    const updated = [text, ...recentSearches.filter((item) => item !== text)].slice(0, 5);
    setRecentSearches(updated);
    localStorage.setItem("recentSearches", JSON.stringify(updated));
  };

  // Handle selection
  const handleSelect = (text) => {
    setQuery(text);
    setShowDropdown(false);
    saveRecentSearch(text);

    const lower = text.toLowerCase();

    const cat = results.categories.find((c) => c.name?.toLowerCase().includes(lower));
    if (cat) return navigate(`/category/${cat._id}`);

    const bus = results.businesses.find((b) => b.businessName?.toLowerCase() === lower);
    if (bus) return navigate(`/category/${bus.businessName}/${bus._id}`);

    const prod = results.products.find((p) => p.name?.toLowerCase() === lower);
    if (prod) return navigate(`/product/${prod._id}`);
  };

  // Voice Search Handler
  const handleVoiceSearch = () => {
    if (!window.webkitSpeechRecognition) return alert("Your browser does not support voice search.");
    const recognition = new window.webkitSpeechRecognition();
    recognition.lang = "en-IN";
    recognition.interimResults = false;
    recognition.continuous = false;
    recognition.onstart = () => setListening(true);
    recognition.onerror = () => setListening(false);
    recognition.onend = () => setListening(false);
    recognition.onresult = (event) => {
      const transcript = event.results[0][0].transcript;
      setQuery(transcript);
      setShowDropdown(true);
    };

    recognition.start();
  };

  return (
    <Box
      sx={{
        width: "100%",
        maxWidth: 600,
        margin: "auto",
        mt: 2,
        mb: 2,
        position: "relative",
        zIndex: 1200,
      }}
    >
      <TextField
        fullWidth
        size="small"
        value={query}
        onChange={(e) => setQuery(e.target.value.trimStart())}
        onClick={() => setShowDropdown(true)}
        onBlur={() => setTimeout(() => setShowDropdown(false), 200)}
        placeholder={`Search ${displayText}...`}
        InputProps={{
          startAdornment: (
            <InputAdornment position="start">
              <SearchIcon color="primary" />
            </InputAdornment>
          ),
          endAdornment: (
            <InputAdornment position="end">
              <IconButton onClick={handleVoiceSearch} size="small">
                <MicIcon color={listening ? "error" : "action"} />
              </IconButton>
            </InputAdornment>
          ),
        }}
        sx={{
          backgroundColor: "#fff",
          borderRadius: 2,
          boxShadow: 2,
        }}
      />

      {showDropdown && (
        <Paper
          elevation={4}
          sx={{
            position: "absolute",
            top: "100%",
            left: 0,
            right: 0,
            mt: 1,
            borderRadius: 2,
            zIndex: 1500,
            maxHeight: 400,
            overflowY: "auto",
            backgroundColor: "#fff",
          }}
        >
          {recentSearches.length > 0 && (
            <Box px={2} pt={1}>
              <Box display="flex" justifyContent="space-between" alignItems="center" mb={1}>
                <Typography variant="subtitle2" fontWeight="bold">Recent</Typography>
                <IconButton size="small" onClick={() => {
                  setRecentSearches([]);
                  localStorage.removeItem("recentSearches");
                }}>
                  <ClearIcon fontSize="small" color="error" />
                </IconButton>
              </Box>
              <List dense>
                {recentSearches.map((item, i) => (
                  <ListItem key={i} button onClick={() => handleSelect(item)}>
                    <ListItemText primary={item} />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}

          <Divider />

          <Box px={2} pt={1}>
            <Typography variant="subtitle2" fontWeight="bold" mb={1}>Popular Categories</Typography>
            <List dense>
              {staticCategories.map((item, i) => (
                <ListItem key={i} button onClick={() => handleSelect(item)}>
                  <ListItemText primary={item} />
                </ListItem>
              ))}
            </List>
          </Box>

          {loading && (
            <Box textAlign="center" py={2}>
              <CircularProgress size={24} />
            </Box>
          )}

          {!loading && results.categories.length > 0 && (
            <Box px={2}>
              <Typography variant="subtitle2" fontWeight="bold">Categories</Typography>
              <List dense>
                {results.categories.map((cat) => (
                  <ListItem key={cat._id} button onClick={() => handleSelect(cat.name)}>
                    <ListItemText primary={cat.name} />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}

          {!loading && results.businesses.length > 0 && (
            <Box px={2}>
              <Typography variant="subtitle2" fontWeight="bold">Businesses</Typography>
              <List dense>
                {results.businesses.map((b) => (
                  <ListItem key={b._id} button onClick={() => handleSelect(b.businessName)}>
                    <ListItemText primary={`${b.businessName} – ${b.city}, ${b.state}`} />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}

          {!loading && results.products.length > 0 && (
            <Box px={2}>
              <Typography variant="subtitle2" fontWeight="bold">Products</Typography>
              <List dense>
                {results.products.map((p) => (
                  <ListItem key={p._id} button onClick={() => handleSelect(p.name)}>
                    <ListItemText primary={`${p.name} – ${p.businessId?.businessName || ""}`} />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}
        </Paper>
      )}
    </Box>
  );
};

export default SearchBar;
