const ProductSlider = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const scrollRef = useRef(null);

  const fetchAllProducts = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get("/api/v1/product/all");
      const productsData = res.data?.allProduct || [];
      setProducts(productsData.slice(0, 8));
    } catch (err) {
      setError("Failed to load products.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAllProducts();
  }, []);

  const scrollLeft = () => {
    scrollRef.current.scrollBy({ left: -300, behavior: "smooth" });
  };

  const scrollRight = () => {
    scrollRef.current.scrollBy({ left: 300, behavior: "smooth" });
  };

  if (loading) {
    return (
      <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Typography color="error" sx={{ textAlign: "center", py: 4 }}>
        {error}
      </Typography>
    );
  }

  return (
    <Box sx={{ px: { xs: 2, sm: 4 }, py: 6, position: "relative" }}>
      <Container maxWidth="xl">
        <Typography
          variant="h5"
          sx={{
            fontWeight: FontWeight.heading1,
            mb: 4,
            fontSize: { xs: "1.5rem", sm: "2rem" },
            color: Colors.LOGOColor,
            borderLeft: "5px solid",
            borderColor: Colors.LOGOlight,
            pl: 2,
            fontFamily: FontFamily.Georgia,
          }}
        >
          Popular Products
        </Typography>

        {/* Arrows */}
        <IconButton
          onClick={scrollLeft}
          sx={{
            position: "absolute",
            top: "50%",
            left: 10,
            transform: "translateY(-50%)",
            zIndex: 2,
            backgroundColor: "#fff",
            "&:hover": { backgroundColor: "#f0f0f0" },
            boxShadow: 1,
            display: { xs: "none", sm: "flex" },
          }}
        >
          <ArrowBackIos sx={{ color: "#000" }} />
        </IconButton>

        <IconButton
          onClick={scrollRight}
          sx={{
            position: "absolute",
            top: "50%",
            right: 10,
            transform: "translateY(-50%)",
            zIndex: 2,
            backgroundColor: "#fff",
            "&:hover": { backgroundColor: "#f0f0f0" },
            boxShadow: 1,
            display: { xs: "none", sm: "flex" },
          }}
        >
          <ArrowForwardIos sx={{ color: "#000" }} />
        </IconButton>

        <Box
          ref={scrollRef}
          sx={{
            display: "flex",
            overflowX: "auto",
            gap: 3,
            pb: 2,
            scrollBehavior: "smooth",
            "&::-webkit-scrollbar": { display: "none" },
          }}
        >
          {products.map((product) => {
            const image =
              typeof product.images?.[0] === "string"
                ? product.images[0]
                : product.images?.[0]?.url;

            return (
              <Box
                key={product._id}
                component={Link}
                to={`/product/${product._id}`}
                sx={{
                  textDecoration: "none",
                  color: "inherit",
                  minWidth: { xs: 250, sm: 280, md: 300 },
                  maxWidth: 320,
                  flexShrink: 0,
                  borderRadius: 2,
                  overflow: "hidden",
                  backgroundColor: "#fff",
                  boxShadow: "0 4px 20px rgba(0,0,0,0.05)",
                  transition: "transform 0.3s, box-shadow 0.3s",
                  "&:hover": {
                    transform: "translateY(-4px)",
                    boxShadow: "0 6px 24px rgba(0,0,0,0.1)",
                  },
                }}
              >
                <Box
                  component="img"
                  src={image}
                  alt={product.name}
                  sx={{
                    width: "100%",
                    height: 200,
                    objectFit: "cover",
                  }}
                />

                <Box sx={{ px: 2, py: 2 }}>
                  <Typography
                    variant="body1"
                    fontWeight={600}
                    noWrap
                    sx={{ mb: 0.5 }}
                  >
                    {product.name}
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      fontWeight: 700,
                      color: Colors.LOGOColor,
                    }}
                  >
                    {product.priceType === "from"
                      ? `From ₹${product.price}`
                      : `Just ₹${product.price}`}
                  </Typography>
                </Box>
              </Box>
            );
          })}
        </Box>
      </Container>
    </Box>
  );
};

export default ProductSlider;

