import React, { useState } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  Container,
  Box,
  IconButton,
  Button,
} from "@mui/material";
import {
  Search as SearchIcon,
  ExitToApp as LogoutIcon,
} from "@mui/icons-material";
import AddCircleOutlineOutlinedIcon from '@mui/icons-material/AddCircleOutlineOutlined';
import { Link, useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { Modal } from "antd";
import { ExclamationCircleOutlined } from "@ant-design/icons";
import LoginIcon from '@mui/icons-material/Login';
import { logout } from '../redux/actions/userAction';
import { Colors, FontSize, FontWeight, FontFamily } from "../Comman"
import SearchBar from "./SearchBar";

const { confirm } = Modal;

const Navbar = () => {
  const [showMobileSearch, setShowMobileSearch] = useState(false);
  const { user } = useSelector((state) => state.user);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const toggleMobileSearch = () => setShowMobileSearch(!showMobileSearch);
  const handleAddBusiness = () => navigate("/plans");

// Logout api 
  const handleLogout = () => {
    confirm({
      title: "Are you sure you want to Log out?",
      icon: <ExclamationCircleOutlined />,
      content: "Your current session will be terminated.",
      onOk() {
        sessionStorage.setItem("justLoggedOut", "true");
        dispatch(logout());
        localStorage.clear();
        navigate("/login", { replace: true });
      },
    });
  };

  return (
    <>
      <AppBar
        position="sticky"
        sx={{
          top: 0,
          zIndex: 1100,
          background: Colors.LOGOColor,
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
        }}
      >
        <Container maxWidth="xl">
          <Toolbar sx={{ justifyContent: "space-between", height: "76px" }}>
            <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Typography
                component={Link}
                to="/"
                variant="h5"
                sx={{
                  fontFamily: FontFamily.arial,
                  fontWeight: FontWeight.bold,
                  color: Colors.WHITE,
                  textDecoration: "none",
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                }}
              >
                Quickdials
              </Typography>
            </Box>
              <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              {/* Desktop Search */}
              <Box sx={{ position: "relative",width: 400, display: { xs: "none", md: "block" } }}>
            <SearchBar />
              </Box>
              <Box sx={{ position: "relative", display: "inline-block" }}>
                <Box 
                  sx={{
                    position: "absolute",
                    display: { xs: "none", md: "flex" },
                    top: -12,
                    left: 10,
                    backgroundColor: Colors.LOGOlight,
                    color: Colors.LOGOColor,
                    borderRadius: "12px",
                    px: 1.5,
                    py: 0.5,
                    fontSize: "10px",
                    fontWeight: 600,
                    fontFamily: FontFamily.arial,
                    zIndex: 1,
                  }}
                >
                  Business
                </Box>
                <Button
                  variant="contained"
                  startIcon={<AddCircleOutlineOutlinedIcon />}
                  onClick={handleAddBusiness}
                  sx={{
                    display: { xs: "none", md: "flex" },
                    backgroundColor: Colors.WHITE,
                    color: Colors.LOGOColor,
                    borderRadius: 2,
                    px: 3,
                    py: 1,
                    fontFamily: FontFamily.arial,
                    textTransform: "none",
                    fontSize: FontSize.fifteen,
                  }}
                >
                  Free Listing
                </Button>
              </Box>

              {/* Mobile Buttons */}
              <Box sx={{ display: { xs: "flex", md: "none" }, gap: 1 }}>
                <IconButton sx={{ color: Colors.WHITE }} onClick={toggleMobileSearch}>
                  <SearchIcon fontSize="large" />
                </IconButton>
                <Box sx={{ position: "relative" }}>
                  <Box
                    sx={{
                      position: "absolute",
                      top: -10,
                      left: "50%",
                      transform: "translateX(-50%)",
                      backgroundColor: Colors.LOGOlight,
                      color: Colors.LOGOColor,
                      borderRadius: "12px",
                      px: 1.2,
                      py: 0.2,
                      fontSize: "10px",
                      fontWeight: 600,
                      fontFamily: FontFamily.arial,
                      whiteSpace: "nowrap",
                      zIndex: 1,
                    }}
                  >
                    Business
                  </Box>
                  <IconButton sx={{ color: Colors.WHITE }} onClick={handleAddBusiness}>
                    <AddCircleOutlineOutlinedIcon fontSize="large" />
                  </IconButton>
                </Box>
              </Box>

              {/* Login Button - Consistent across devices */}
              {user && user._id ? (
                <Button
                  onClick={handleLogout}
                  startIcon={<LogoutIcon />}
                  sx={{
                    backgroundColor: Colors.WHITE,
                    color: Colors.LOGOColor,
                    textTransform: "none",
                    fontFamily: FontFamily.arial,
                    fontSize: FontSize.fifteen,
                    borderRadius: 2,
                    px: 2,
                    py: 0.8,
                  }}
                >
                  Logout
                </Button>
              ) : (
                <Button
                  component={Link}
                  to="/login"
                  startIcon={<LoginIcon />}
                  sx={{
                    backgroundColor: Colors.WHITE,
                    color: Colors.LOGOColor,
                    textTransform: "none",
                    fontFamily: FontFamily.arial,
                    fontSize: FontSize.fifteen,
                    borderRadius: 2,
                    px: 2,
                    py: 0.8,
                  }}
                >
                  Login
                </Button>
              )}
            </Box>
          </Toolbar>
        </Container>

        {/* Mobile Search Bar */}
        {showMobileSearch && (
          <SearchBar />
        )}
      </AppBar>

      {/* Spacer */}
      <Box sx={{ height: "76px" }} />
    </>
  );
};

export default Navbar;